import { readFile } from 'node:fs/promises'
import { parseProjectsConfig } from '/home/agentops/dev/md-manager-ultra/server/projectsConfig.ts'
import { ProjectApiError, RunStore } from '/home/agentops/dev/md-manager-ultra/server/projects.ts'

function describe(error: unknown): string {
  if (error instanceof ProjectApiError) return `${error.status} ${error.code}: ${error.message}`
  return `THROWN ${(error as Error).stack ?? String(error)}`
}

async function main() {
  const configPath = process.argv[2]
  const config = await parseProjectsConfig(await readFile(configPath, 'utf8'), 'audit registry')
  const store = new RunStore(config, { warn: (message, details) => console.log('WARN', message, JSON.stringify(details)) })
  for (const project of config.projects) {
    for (const workflow of project.workflows) {
      const scope = store.scope(project.project_id, workflow.workflow_id)
      console.log(`\n=== workflow ${workflow.workflow_id}`)
      let runs
      try {
        runs = await store.listRuns(scope)
        console.log('listRuns:', runs.map(run => `${run.run_id}:${run.status}`).join(', ') || '(none)')
      } catch (error) {
        console.log('listRuns FAILED:', describe(error))
        continue
      }
      for (const run of runs) {
        try {
          const loaded = await store.loadRun(scope, run.run_id)
          const review = loaded.detail.snapshot.nodes.find(node => node.node_id === 'review')
          console.log(`loadRun ok: status=${loaded.detail.summary.status} review node=${JSON.stringify(review)}`)
          console.log('  review:', loaded.review === null ? 'null' : JSON.stringify({ transport: loaded.review.reviewer.transport, verdict: loaded.review.verdict, reviewed_at: loaded.review.reviewed_at, diff: loaded.review.diff, findings: loaded.review.findings }))
          if (loaded.inputs === null) console.log('  inputs: null')
          else {
            const { workers, ...rest } = loaded.inputs
            console.log('  inputs:', JSON.stringify(rest))
            for (const worker of workers) {
              const { task, prompt, checks, ...w } = worker
              console.log(`  worker ${worker.node_id}:`, JSON.stringify({ ...w, task: task.text.length, prompt: prompt === null ? null : prompt.text.length, checks: checks.map(check => `${check.id}=${check.command}`) }))
            }
          }
        } catch (error) {
          console.log('loadRun FAILED:', describe(error))
          continue
        }
        for (const attempt of [1]) {
          try {
            const result = await store.reviewResult(scope, run.run_id, attempt)
            console.log(`  reviewResult(${attempt}) ok: verdict=${result.verdict} findings=${result.findings.length}`)
            if (result.diff) {
              try {
                const artifact = await store.artifact(scope, run.run_id, result.diff.artifact_id)
                console.log(`  diff artifact ok: ${artifact.kind} ${artifact.contentType} ${artifact.bytes.length} bytes`)
              } catch (error) {
                console.log('  diff artifact FAILED:', describe(error))
              }
            }
          } catch (error) {
            console.log(`  reviewResult(${attempt}):`, describe(error))
          }
        }
        try {
          const inputs = await store.runInputs(scope, run.run_id)
          console.log(`  runInputs ok: mode=${inputs.mode} workers=${inputs.workers.map(w => w.node_id).join(',')}`)
        } catch (error) {
          console.log('  runInputs:', describe(error))
        }
      }
    }
  }
}

main().catch(error => { console.error('FATAL', error); process.exit(1) })

